#include <queue>
using namespace std;
char mazeA[20][20], mazeB[20][20];
queue<pair<int,int>> q;
int distA[20][20], distB[11][11][11][11];
int dx[4]={-1,1,0,0}, dy[4]={0,0,-1,1};
struct Edge {
    int u,v,flow,capacity,next;
} e[200005];
int cnt, head[505], p[505], v[505], s=501, t=502, totalFlow, n, m, dep[505];

inline void addEdge(int u, int v, int w) {
    e[++cnt]={u,v,0,w,head[u]};
    head[u]=cnt;
    e[++cnt]={v,u,0,0,head[v]};
    head[v]=cnt;
}

inline bool bfs() {
    queue<int> q2;
    for(int i=0;i<=t;i++) { v[i]=0; dep[i]=0; }
    q2.push(s);
    v[s]=1;
    dep[s]=1;
    while(!q2.empty()) {
        int x=q2.front(); q2.pop();
        for(int i=head[x];i;i=e[i].next) {
            if(!v[e[i].v] && e[i].flow<e[i].capacity) {
                p[e[i].v]=i;
                q2.push(e[i].v);
                v[e[i].v]=1;
                dep[e[i].v]=dep[x]+1;
                if(e[i].v==t) return true;
            }
        }
    }
    return false;
}

inline int dfs(int x, int flow) {
