    int tFlow=flow;
    for(int i=head[x];i;i=e[i].next) {
        if(e[i].capacity>e[i].flow && dep[e[i].v]==dep[x]+1) {
            int delta=dfs(e[i].v, min(tFlow, e[i].capacity - e[i].flow));
            if(delta==0) dep[e[i].v]=0;
            e[i].flow+=delta;
            e[((i-1)^1)+1].flow-=delta;
            tFlow-=delta;
            if(tFlow==0) break;
        }
    }
    return flow - tFlow;
}

inline void runDinic() {
    while(bfs()) totalFlow+=dfs(s, 1000000007);
}

