import java.util.*;

public class Main {
    static char[][] mazeA = new char[20][20];
    static char[][] mazeB = new char[20][20];
    static Queue<int[]> q = new LinkedList<>();
    static int[][] distA = new int[20][20];
    static int[][][][] distB = new int[20][20][20][20];
    static List<Edge> edges = new ArrayList<>();
    static int[] head;
    static int[] p;
    static int[] v;
    static int s = 501;
    static int t = 502;
    static int totalFlow = 0;
    static int n, m;
    static int[] dep;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static List<Integer>[] adj;

    static class Edge {
        int u, v, flow, capacity, rev;

        public Edge(int u, int v, int flow, int capacity, int rev) {
            this.u = u;
            this.v = v;
            this.flow = flow;
            this.capacity = capacity;
            this.rev = rev;
        }
    }

    static void addEdge(int u, int v, int w) {
        adj[u].add(edges.size());
        edges.add(new Edge(u, v, 0, w, edges.size() + 1));
        adj[v].add(edges.size());
        edges.add(new Edge(v, u, 0, 0, edges.size() - 1));
    }

    static boolean bfs() {
        Arrays.fill(v, 0);
        Arrays.fill(dep, 0);
        Queue<Integer> q2 = new LinkedList<>();
        q2.offer(s);
        v[s] = 1;
        dep[s] = 1;
        while (!q2.isEmpty()) {
            int x = q2.poll();
            for (int i : adj[x]) {
                Edge e = edges.get(i);
                if (v[e.v] == 0 && e.flow < e.capacity) {
                    p[e.v] = i;
                    q2.offer(e.v);
                    v[e.v] = 1;
                    dep[e.v] = dep[x] + 1;
                    if (e.v == t) return true;
                }
            }
        }
        return false;
    }

    static int dfs(int x, int flow) {
        if (x == t || flow == 0) return flow;
        int tFlow = flow;
        for (int i = p[x]; i < adj[x].size(); i = p[x]) {
            Edge e = edges.get(i);
            if (e.capacity > e.flow && dep[e.v] == dep[x] + 1) {
                int delta = dfs(e.v, Math.min(tFlow, e.capacity - e.flow));
                if (delta == 0) dep[e.v] = 0;
                e.flow += delta;
                edges.get(e.rev).flow -= delta;
                tFlow -= delta;
                if (tFlow == 0) break;
            }
        }
        return flow - tFlow;
    }

    static void runDinic() {
        while (bfs()) {
            totalFlow += dfs(s, Integer.MAX_VALUE);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int tLimit = sc.nextInt();

        for (int i = 0; i < 20; i++) {
            Arrays.fill(distA[i], 10000);
        }

        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 20; j++) {
                mazeA[i][j] = sc.next().charAt(0);
            }
        }

        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 20; j++) {
                distA[i][j] = 10000;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                distA[i][j] = 10000;
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (mazeA[i][j] == 'Z') {
                    q.offer(new int[]{i, j});
                    distA[i][j] = 0;
                }
            }
        }

        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && ny >= 0 && nx < n && ny < n && mazeA[nx][ny] <= '9' && distA[nx][ny] > distA[x][y] + 1) {
                    distA[nx][ny] = distA[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }

        adj = new ArrayList[505];
        for (int i = 0; i <= 505; i++) {
            adj[i] = new ArrayList<>();
        }
        p = new int[505];
        v = new int[505];
        dep = new int[505];

        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 20; j++) {
                for (int k = 0; k < 20; k++) {
                    for (int l = 0; l < 20; l++) {
                        distB[i][j][k][l] = 10000;
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (mazeA[i][j] > '9') continue;
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        distB[i][j][k][l] = 10000;
                    }
                }
                q.clear();
                distB[i][j][i][j] = 0;
                q.offer(new int[]{i, j});
                while (!q.isEmpty()) {
                    int[] pos = q.poll();
                    int x = pos[0], y = pos[1];
                    for (int f = 0; f < 4; f++) {
                        int nx = x + dx[f], ny = y + dy[f];
                        if (nx >= 0 && ny >= 0 && nx < n && ny < n && mazeA[nx][ny] <= '9' && distB[i][j][nx][ny] > distB[i][j][x][y] + 1 && distA[x][y] < distA[nx][ny]) {
                            distB[i][j][nx][ny] = distB[i][j][x][y] + 1;
                            q.offer(new int[]{nx, ny});
                        }
                    }
                }
                for (int k2 = 0; k2 < n; k2++) {
                    for (int l2 = 0; l2 < n; l2++) {
                        if (distB[i][j][k2][l2] <= Math.min(distA[k2][l2], tLimit))
                            addEdge((i * n + j), (k2 * n + l2 + 100), 10000);
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                mazeB[i][j] = sc.next().charAt(0);
                if (mazeB[i][j] <= '9') {
                    addEdge((i * n + j + 100), t, mazeB[i][j] - '0');
                }
            }
        }

        runDinic();

        System.out.println(totalFlow);
        sc.close();
    }
